"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["94706"],{5805(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.promocao_sem_revisao","status":422,"titulo":"S\xf3 um rascunho marcado como revisado pode ser promovido a vers\xe3o"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.promocao_sem_revisao","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["A promo\xe7\xe3o (`POST /api/configuracao/admin/termos-consentimento/{id}/promover`) transforma o rascunho numa vers\xe3o imut\xe1vel do termo, e s\xf3 aceita um rascunho marcado como revisado por uma verifica\xe7\xe3o pr\xf3pria (UNI-REQ-0086). O rascunho do termo n\xe3o est\xe1 nesse estado. Isso acontece em tr\xeas situa\xe7\xf5es:","- a revis\xe3o nunca foi marcada;\\n- o texto, a base legal ou a forma de aceite do rascunho foi editado depois da revis\xe3o, o que limpa a marca, porque a revis\xe3o vale para o conte\xfado exato que foi lido;\\n- a revis\xe3o j\xe1 foi usada por uma promo\xe7\xe3o: cada vers\xe3o exige a sua pr\xf3pria revis\xe3o, e uma segunda chamada de promo\xe7\xe3o logo em seguida recebe esta recusa em vez de duplicar a vers\xe3o.","A busca do termo vem antes: com um `{id}` que n\xe3o existe, a resposta \xe9 a de termo n\xe3o encontrado (`uniplus.configuracao.termo_consentimento.nao_encontrado`). Nada \xe9 gravado."],"comoResolver":["Marque o rascunho como revisado (`POST /api/configuracao/admin/termos-consentimento/{id}/revisar`) depois da \xfaltima edi\xe7\xe3o e promova em seguida. Se a resposta anterior de uma promo\xe7\xe3o se perdeu, consulte o termo (`GET /api/configuracao/termos-consentimento/{id}`) e confira se a vers\xe3o j\xe1 consta na lista de vers\xf5es promovidas antes de repetir o processo."],"ondeAparece":["Promo\xe7\xe3o do rascunho de um termo de consentimento a vers\xe3o"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);